#!/bin/sh
# Проверява страниците в браузъра (dev сървър на :5179) при 1280 и 390 px, с отворени решения.
# sh scripts/tex/check-all.sh [страница…]   (по подразбиране – всички уроци)
cd "$(dirname "$0")/../.."
PAGES="$*"
if [ -z "$PAGES" ]; then
  PAGES="arithmetic/addition arithmetic/subtraction arithmetic/multiplication arithmetic/division arithmetic/mixed algebra/fractions algebra/powers algebra/logarithms algebra/linear algebra/quadratic algebra/systems algebra/matrices algebra/inequalities algebra/olympiad-inequalities algebra/sequences algebra/complex numbers/number-sets numbers/divisibility numbers/gcd numbers/modular functions/linear functions/quadratic functions/grapher analysis/limits analysis/derivatives analysis/integrals analysis/differential-equations geometry/triangle geometry/similar geometry/trigonometry geometry/vectors geometry/quadrilateral geometry/polygons geometry/circle geometry/solids probability/combinatorics probability/basics physics/mechanics/units physics/mechanics/linear-motion physics/mechanics/plane-motion physics/mechanics/newton physics/mechanics/energy physics/mechanics/momentum physics/mechanics/rotation physics/mechanics/statics-fluids physics/waves/oscillations physics/waves/waves physics/waves/sound physics/heat/temperature physics/heat/ideal-gas physics/heat/thermodynamics physics/electricity/electrostatics physics/electricity/capacitors physics/electricity/direct-current physics/electricity/magnetic-field physics/electricity/induction physics/electricity/ac-em-waves physics/optics/reflection-refraction physics/optics/lenses physics/optics/wave-optics physics/modern/photons physics/modern/atom physics/modern/nucleus physics/modern/uncertainty physics/modern/particle-in-box physics/modern/quantum-atom chemistry/structure/substances chemistry/structure/atoms chemistry/structure/bonding chemistry/structure/molecules chemistry/quantities/mole chemistry/quantities/stoichiometry chemistry/quantities/solutions chemistry/quantities/gases chemistry/reactions/energy chemistry/reactions/kinetics chemistry/reactions/equilibrium chemistry/reactions/acids-bases chemistry/reactions/redox chemistry/inorganic/metals chemistry/inorganic/nonmetals chemistry/inorganic/compound-classes chemistry/inorganic/qualitative-analysis chemistry/organic/hydrocarbons chemistry/organic/functional-groups chemistry/organic/mechanisms chemistry/organic/polymers chemistry/organic/biomolecules chemistry/world/nuclear chemistry/world/environment chemistry/world/spectroscopy biology/cell/life biology/cell/structure biology/cell/membrane biology/cell/division biology/energy/enzymes biology/energy/respiration biology/energy/photosynthesis biology/genetics/dna biology/genetics/mendel biology/genetics/human biology/genetics/biotech biology/evolution/selection biology/evolution/phylogeny biology/evolution/microbes biology/evolution/classification biology/plants/transport biology/plants/growth biology/physiology/digestion biology/physiology/circulation biology/physiology/breathing biology/physiology/homeostasis biology/physiology/nerves biology/physiology/hormones biology/physiology/immunity biology/physiology/reproduction biology/ecology/ecosystems biology/ecology/populations biology/ecology/biodiversity biology/ecology/behaviour geography/maps/coordinates geography/maps/projections geography/maps/topography geography/maps/gis geography/lithosphere/interior geography/lithosphere/plates geography/lithosphere/hazards geography/lithosphere/landforms geography/atmosphere/energy geography/atmosphere/moisture geography/atmosphere/circulation geography/atmosphere/weather geography/atmosphere/climate geography/atmosphere/climate-change geography/hydrosphere/ocean geography/hydrosphere/rivers geography/hydrosphere/groundwater geography/hydrosphere/biomes geography/population/demography geography/population/migration geography/population/cities geography/economy/resources geography/economy/agriculture geography/economy/industry geography/economy/globalization geography/regions/world geography/regions/europe geography/regions/bulgaria-nature geography/regions/bulgaria-society"
  PAGES="$PAGES ai/history/thinking-machines ai/history/rules-vs-learning ai/history/deep-learning-era ai/models/data ai/models/regression ai/models/classification ai/models/trees ai/models/clustering ai/models/evaluation ai/learning/loss ai/learning/gradient-descent ai/learning/backprop ai/networks/neuron ai/networks/training ai/networks/convolution ai/networks/vision ai/language/tokens ai/language/embeddings ai/language/attention ai/language/transformer ai/language/generation ai/language/assistants"
  PAGES="$PAGES astronomy/sky/intro astronomy/sky/celestial-sphere astronomy/sky/coordinates astronomy/sky/earth-motion astronomy/sky/moon-phases astronomy/sky/eclipses astronomy/gravity/gravitation astronomy/gravity/kepler astronomy/gravity/orbits astronomy/light/spectra astronomy/light/telescopes astronomy/light/observing-methods astronomy/solar-system/sun astronomy/solar-system/solar-activity astronomy/solar-system/terrestrial-planets astronomy/solar-system/gas-giants astronomy/solar-system/small-bodies astronomy/solar-system/comets astronomy/solar-system/asteroids astronomy/stars/stars astronomy/stars/hr-diagram astronomy/stars/evolution astronomy/stars/compact-objects astronomy/stars/binaries astronomy/stars/variables astronomy/universe/distances astronomy/universe/galaxies astronomy/universe/milky-way astronomy/universe/big-bang astronomy/universe/expansion astronomy/universe/dark-matter astronomy/universe/relativity astronomy/life/exoplanets astronomy/life/astrobiology"
fi
for page in $PAGES; do
  for w in 1280 390; do
    agent-browser set viewport $w 900 >/dev/null
    agent-browser open "http://localhost:5179/$page" >/dev/null
    agent-browser wait 1200 >/dev/null
    agent-browser eval --stdin < scripts/tex/expand.js >/dev/null
    agent-browser wait 300 >/dev/null
    r=$(agent-browser eval --stdin < scripts/tex/check.js 2>&1)
    if echo "$r" | grep -q 'errors\\":\[\],\\"rawDollar\\":\[\],\\"overflow\\":\[\]'; then
      echo "ok   $page $w $(echo "$r" | grep -o 'katex[^,]*')"
    else
      echo "FAIL $page $w $r"
    fi
  done
done
